export function fresh(seed=7319){return {version:1,seed,room:0,health:5,memories:[],status:'playing',cooldown:0,invincible:0,elapsed:0,artifact:false,deaths:0}}
export function remember(s,id){if(!Number.isInteger(id)||id<0||id>=MEMORIES.length||s.memories.includes(id))return null;s.memories.push(id);return MEMORIES[id]}
export function damage(s){if(s.invincible>0||s.status!=='playing')return false;s.health=Math.max(0,s.health-1);s.invincible=2.5;if(!s.health)s.status='lost';return true}
export function save(s,storage){try{storage.setItem('karakurt-save',JSON.stringify(s));return true}catch{return false}}
export function restore(storage){try{const v=JSON.parse(storage.getItem('karakurt-save'));if(!v||v.version!==1||!Number.isSafeInteger(v.seed)||!Number.isSafeInteger(v.room)||v.room<0||!Array.isArray(v.memories))return null;const s=fresh(v.seed);s.room=v.room;s.memories=[...new Set(v.memories.filter(n=>Number.isInteger(n)&&n>=0&&n<5))];s.health=Math.max(1,Math.min(5,Number(v.health)||5));s.artifact=v.artifact===true;s.deaths=Math.max(0,Math.min(100000,Number(v.deaths)||0));return s}catch{return null}}
export function perception({distance,dot,occluded,noise,dt},brain){
 const visible=!occluded&&distance<8&&dot>.45
 if(visible){brain.alert=Math.min(1,brain.alert+dt*(distance<3?2:.8));brain.lost=0}else{brain.lost+=dt;brain.alert=Math.max(0,brain.alert-dt*.16)}
 if(visible&&brain.alert>.65)brain.mode='Chase';else if(brain.mode==='Chase'&&brain.lost<4){}else if(noise||brain.alert>.15)brain.mode='Suspicion';else brain.mode='Patrol'
 return brain.mode
}
